CREATE TABLE peg_approval_tasks (task_id TEXT PRIMARY KEY, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE peg_task_decisions (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, actor_id TEXT NOT NULL, at INTEGER NOT NULL, revision TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('approve','changes','reject')), reason TEXT NOT NULL);
CREATE TABLE peg_decision_guards (task_id TEXT PRIMARY KEY);
CREATE TRIGGER peg_approval_complete BEFORE UPDATE OF status ON peg_tasks
WHEN NEW.status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM peg_decision_guards WHERE task_id=NEW.id)
BEGIN SELECT RAISE(ABORT,'approval_decision_required'); END;
CREATE TABLE peg_work_templates (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, version INTEGER NOT NULL, snapshot TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE peg_recurrences (id TEXT PRIMARY KEY, template_id TEXT NOT NULL, workspace_id TEXT NOT NULL, created_by TEXT NOT NULL, config TEXT NOT NULL, next_date TEXT NOT NULL, last_object_id TEXT NOT NULL, generated INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, last_error TEXT);
CREATE TABLE peg_occurrences (schedule_id TEXT NOT NULL, local_date TEXT NOT NULL, object_id TEXT NOT NULL, created_at INTEGER NOT NULL, template_id TEXT NOT NULL, PRIMARY KEY(schedule_id,local_date));
CREATE TABLE peg_template_origins (object_type TEXT NOT NULL, object_id TEXT NOT NULL, template_id TEXT NOT NULL, source_id TEXT NOT NULL, PRIMARY KEY(object_type,object_id));
CREATE TRIGGER peg_templates_immutable BEFORE UPDATE ON peg_work_templates BEGIN SELECT RAISE(ABORT,'immutable_template'); END;
CREATE TRIGGER peg_decisions_immutable BEFORE UPDATE ON peg_task_decisions BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TRIGGER peg_decisions_no_delete BEFORE DELETE ON peg_task_decisions BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
CREATE TRIGGER peg_recurrence_revision AFTER UPDATE ON peg_recurrences BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_approval_invalidate_peg_field_values_insert AFTER INSERT ON peg_field_values BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_field_values_update AFTER UPDATE ON peg_field_values BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_field_values_delete AFTER DELETE ON peg_field_values BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=OLD.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.task_id); END;
