CREATE TRIGGER peg_approval_invalidate_peg_comments_delete AFTER DELETE ON peg_comments BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=OLD.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.task_id); END;
