CREATE TRIGGER peg_approval_invalidate_peg_task_collaborators_update AFTER UPDATE ON peg_task_collaborators BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_task_collaborators_delete AFTER DELETE ON peg_task_collaborators BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=OLD.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_task_tags_insert AFTER INSERT ON peg_task_tags BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_task_tags_update AFTER UPDATE ON peg_task_tags BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_invalidate_peg_task_tags_delete AFTER DELETE ON peg_task_tags BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=OLD.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.task_id); END;
CREATE TABLE peg_project_completion (project_id TEXT PRIMARY KEY, at INTEGER NOT NULL);
CREATE TRIGGER peg_project_completed AFTER UPDATE OF status ON peg_projects WHEN NEW.status IN ('done','completed') AND OLD.status NOT IN ('done','completed')
BEGIN INSERT OR REPLACE INTO peg_project_completion VALUES(NEW.id,CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)); END;
CREATE TRIGGER peg_review_revision_peg_tags_insert AFTER INSERT ON peg_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_tags_update AFTER UPDATE ON peg_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_tags_delete AFTER DELETE ON peg_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_tag_projects_insert AFTER INSERT ON peg_tag_projects BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_tag_projects_update AFTER UPDATE ON peg_tag_projects BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_tag_projects_delete AFTER DELETE ON peg_tag_projects BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_task_tags_insert AFTER INSERT ON peg_task_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_task_tags_update AFTER UPDATE ON peg_task_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_review_revision_peg_task_tags_delete AFTER DELETE ON peg_task_tags BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_approval_membership_insert AFTER INSERT ON peg_task_projects BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_membership_update AFTER UPDATE ON peg_task_projects BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=NEW.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=NEW.task_id); END;
CREATE TRIGGER peg_approval_membership_delete AFTER DELETE ON peg_task_projects BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE id=OLD.task_id AND status='done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.task_id); END;
CREATE TRIGGER peg_approval_field_definition AFTER UPDATE ON peg_field_definitions BEGIN UPDATE peg_tasks SET status='todo',completed_at=NULL WHERE status='done' AND id IN (SELECT task_id FROM peg_approval_tasks) AND (id IN (SELECT task_id FROM peg_field_values WHERE field_id=NEW.id) OR id IN (SELECT tp.task_id FROM peg_task_projects tp JOIN peg_project_fields f ON f.project_id=tp.project_id WHERE f.field_id=NEW.id)); END;
